#include <stdio.h>
#include <stdlib.h>

typedef struct T { int v; struct T *l, *r; } T;
static T *ins(T *n, int v) {
    if (!n) { T *x = malloc(sizeof(T)); x->v = v; x->l = x->r = NULL; return x; }
    if (v < n->v) n->l = ins(n->l, v);
    else if (v > n->v) n->r = ins(n->r, v);
    return n;
}
static int prev = -1, ok = 1;
static void ino(T *n) {
    if (!n) return;
    ino(n->l);
    if (prev >= 0) {
        printf(" %d", n->v);
        if (n->v <= prev) ok = 0;      /* 必须严格递增 */
    } else printf(" %d", n->v);
    prev = n->v;
    ino(n->r);
}
int main(void) {
    int vals[] = {50, 30, 70, 20, 40, 60, 80};
    T *root = NULL;
    for (int i = 0; i < 7; i++) root = ins(root, vals[i]);
    printf("中序:");
    ino(root);
    printf("\n是否严格递增: %s\n", ok ? "是（是合法 BST）" : "否");
    return 0;
}
